# Find the exact phrase and print a larger surrounding window to inspect the context more thoroughly
import re
pattern = r"Stevens Institute of Technology"
m = re.search(pattern, context)
if m:
    start = max(0, m.start() - 500)
    end = min(len(context), m.end() + 500)
    print("Exact phrase found. Context window (±500 chars):\n")
    print(context[start:end])
else:
    # fall back to the earlier match "Stevens"
    m2 = re.search(r"Stevens", context)
    if m2:
        start = max(0, m2.start() - 500)
        end = min(len(context), m2.end() + 500)
        print("Fallback 'Stevens' found. Context window (±500 chars):\n")
        print(context[start:end])
    else:
        print("No occurrences found.")
